WITH valid_store_sales AS (SELECT *, YEAR(sale_date) sale_date_year FROM store_sales WHERE sale_date < '2024-01-01'), store_sales_stats AS (SELECT DATE_FORMAT(sale_date, 'yyyy-MM') sale_month, ROUND(STDDEV(units), 2) stddev_units, MIN(sale_date) min_sale_date FROM valid_store_sales GROUP BY DATE_FORMAT(sale_date, 'yyyy-MM')) SELECT sale_month, min_sale_date FROM store_sales_stats WHERE stddev_units < 72 ORDER BY sale_month ASC;
